INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Milita Aventuro', '游戏的背景是90年代的东欧国家，讲述两个虚构民族艾斯佩罗族和伊多诺族的战争，主人公是一位艾斯佩罗族的少女，玩家要操纵她在战争中游历冒险，期间会遇到各种各样的朋友和敌人。游戏由探索对话和炮弹躲避玩法，目前游戏只制作到序章部分，每制作完成一章就会进行更新。' FROM games WHERE igdb_id = 218711 ON CONFLICT (game_id, language_code) DO NOTHING;
