INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Striker', 'Pixel Game Maker Series THUNDER STRIKER is a vertical scrolling shooter with a retro flavor. You can choose between a laser and a wide range of trajectories for your primary weapon, and three different power-ups for your subweapons! Each weapon can be powered up to five levels. so find the most advantageous combination for each stage and boss! The enemies that stand in your way will attack you with a variety of weapons, including ballistic missiles and guided missiles. In a pinch, use the Bomber for emergency evasion, and enjoy hardcore play! The "Pixel Game Maker Series" is a series of games created using the action game creation software "Pixel Game Maker MV" that can be enjoyed on the Nintendo Switch.' FROM games WHERE igdb_id = 187478 ON CONFLICT (game_id, language_code) DO NOTHING;
