INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy Creeps', 'Play as Elma and Harper, two tweens who may or may not have inadvertently summoned the evil Pumpking, who has swiped the whole neighborhood''s Halloween candy and hidden it inside his army of tiny, adorable decorative gourds. Smash the pumpkins to find candy, then chow down. Once you''re turbo-charged with sugar, transform into a costume-clad avenger and bash the Pumpking until he explodes! Master four unique levels and go for a high score in one- and two-player modes.' FROM games WHERE igdb_id = 227814 ON CONFLICT (game_id, language_code) DO NOTHING;
