INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All in Love and War', 'Gunnery Sergeant Jayden Jones is grudgingly going through the motions of a brutal Marine life he can’t escape from when suddenly he finds himself at risk by the law for blossoming a relationship with his Sergeant Major, Walter Hardy. Under Marine Law, these two are forbidden to be together, so Jayden will have to bear great misfortune and find out what part of himself he’s really missing' FROM games WHERE igdb_id = 205724 ON CONFLICT (game_id, language_code) DO NOTHING;
