INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('biker-garage-mechanic-simulator', 186935, '2022-01-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4d3w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ca7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biker Garage: Mechanic Simulator', 'Biker Garage: Mechanic Simulator allows you to be a top motorcycle mechanic. Your main aim is to be the best mechanic you can, with loads of really happy clients. You start your adventure in a small home workshop which you will need to grow to become the best motorcycle mechanic in the world. Test your bikes on a track, check the quality of your repairs and improve bike performance with fine-tuning. Not only do you customize motorcycles at the request of customers, but you can also create your own dream machine. Find a bike at the junkyard or buy it from a shop and change it beyond recognition while choosing from hundreds of different parts. When you expand your business (and your garage), you will unlock new features like the auction system, racing, and further skills for more difficult tasks.' FROM games WHERE igdb_id = 186935 ON CONFLICT (game_id, language_code) DO NOTHING;
