INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Bunny', 'Killer Bunny is an action-based platformer where players will traverse wild lands as a bunny protagonist, hunting the wretched spiders and snakes that killed their parents. At the end of the game, the bunny will face “Daddy Snake” and “Mommy Spider” — the primordial beings responsible for all spider and snake spawn.' FROM games WHERE igdb_id = 249427 ON CONFLICT (game_id, language_code) DO NOTHING;
