INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emanate', 'Emanate is a single-level, vertical world filled with jumping patterns made up of various platforming mechanics. The most common of which are the orange/red bounce pads, purple wall-jump pads, and the fading platforms, that vanish from under your feet after a very short amount of time. Combining these simple mechanics urges you to keep moving forward, making for some incredibly challenging and intense platforming gameplay.' FROM games WHERE igdb_id = 173418 ON CONFLICT (game_id, language_code) DO NOTHING;
