INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perfect Tides', 'Perfect Tides is a point and click adventure game about the agony and anticipation of being a teen. Set in the year 2000, you play as Mara, an internet-obsessed young writer who lives on a so-called island paradise. Following 4 seasons of the year, you experience through Mara the beauty and silence of the island, the turmoil of family life and mainland public school, and an ever-evolving quest for love, friendship and experience.' FROM games WHERE igdb_id = 169630 ON CONFLICT (game_id, language_code) DO NOTHING;
