INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mokoko X Deluxe', 'Mokoko X was inspired from the arcade games like Volfied, Qix and Gals Panic. A popular gaming style in the late 1980’s, Mokoko X looks to resurrect the soul of the arcade genre while adding a modern touch. There are 32 levels in Mokoko X; each level has its own unique boss and minions. The main goal is assisting the girls that need help from the weird bosses. This is sometimes passing a mobile game level, sometimes helping out with the insects in the kitchen.' FROM games WHERE igdb_id = 246636 ON CONFLICT (game_id, language_code) DO NOTHING;
