INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skábma: Snowfall', 'The rhythm of nature is in danger! You are Áilu, a young Sámi whose ordinary reindeer herding day turns into an adventure. Learn the old ways of the Noaidis, Sámi Healers. Harness the powers of the Noaidi Drum and the Familiar Spirits to fight against a disorder spreading across the land!' FROM games WHERE igdb_id = 114724 ON CONFLICT (game_id, language_code) DO NOTHING;
