INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Potion Master', 'Markus, the young apprentice of a local potion master, has barely started his apprenticeship when trouble began - his master, Zabella, was found lifeless (but not quite dead) on the floor of her own underground lab. The local doctor can only do so much, leaving it up to Markus to investigate his master''s mysterious collapse and -hopefully- find a way to cure her.' FROM games WHERE igdb_id = 232549 ON CONFLICT (game_id, language_code) DO NOTHING;
