INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agtnan: Monster Shutdown Sequence', 'Agtnan is a single player 3D first-person action game where the player, as an escaping robot, endeavors to survive a horde of nightmarish monsters, either by eluding their detection or killing them before they kill you. Set in various outlandish arenas, from underground storage bunkers to floating platforms composed of rotating gears to factories replete with conveyor belts and portals, the variety and uniqueness of each map gives each its own character.' FROM games WHERE igdb_id = 116022 ON CONFLICT (game_id, language_code) DO NOTHING;
