INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-trek-prodigy-supernova', 202419, '2022-10-14', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5375.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1u52.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Prodigy: Supernova', 'After the U.S.S. Protostar picks up strange readings from a dying star, Dal and Gwyn must race against time to save their friends, their ship, and an entire planetary system before a supernova destroys them all! Using their unique skills to overcome ingenious puzzles, endure hostile environments and battle deadly robot armies, Dal and Gwyn must save their captured crewmates Jankom Pog, Rok-Tahk, Zero, and Murf. But they soon encounter a deadly new enemy, one that will stop at nothing to destroy the U.S.S. Protostar and change the very course of history!' FROM games WHERE igdb_id = 202419 ON CONFLICT (game_id, language_code) DO NOTHING;
