INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nora''s AdventurEscape', 'After a life-changing accident ends your career as an Olympic ice skating champion, it''s time for you, Nora Crawford, to find your new life''s purpose! And where better to start looking than your childhood hero''s hometown? But a quick visit brings new challenges when you find the town''s residents preparing for an annual county competition and well on their way to another loss. Can you help the town win the grand prize, discover more about your hero and yourself, and even find true love? Find out in this Hidden-Object Puzzle game!' FROM games WHERE igdb_id = 188227 ON CONFLICT (game_id, language_code) DO NOTHING;
