INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('accidental-woman', 140107, '2022-02-06', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Accidental Woman', 'Accidental Woman is an erotic life simulation game that combines richly detailed fiction and player control to create an immersive experience. Players take on the role of a woman living in Appletree, a small town surrounded by old-wood forests and home to the Institute, where they will manage their character''s relationships, career, mental health, and more while exploring the unique circumstances surrounding the town and their own transformation. The game features customizable clothing options, procedurally generated NPCs with story threads, and various story arcs including main, job, environment, and random events. With the ability to play your way and create complex characters through extensive NPC customization, Accidental Woman offers endless opportunities for players to experiment, challenge themselves, and experience erotic fiction in a dynamic and rewarding manner.' FROM games WHERE igdb_id = 140107 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 140107 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
