INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sheeplings--1', 203522, '2022-05-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ts6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch81l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sheeplings', 'With ''Sheeplings'' children can discover the use of mobile devices and their possibilities in a gentle way. The app lets children experience a day of a lamb and its mother in a blooming meadow. There are no rules, goals or tasks. When children engage with the digital device for the first time, they can observe the lovingly designed and animated animals. Simple touch gestures can then be used to discover the interactivity of the game: The sheep follow the finger or can be stroked. A technically sophisticated simulation makes it a lot of fun to stroke the grass with your fingers. And children who have already tried out the app loved making the colorful flowers literally sound. The playful and self-directed experience is not disturbed by any menus. At the beginning, the game explains to parents how to prevent accidental switching to other apps. The duration of the game can also be set here. After the time has expired, the day comes to an end with a sunset. When the sheep lies down to sleep, the interaction options end and the game comes to an end.' FROM games WHERE igdb_id = 203522 ON CONFLICT (game_id, language_code) DO NOTHING;
