INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mess Quest', 'In Mess Quest, arrive at the aftermath of numerous wacky scenarios to clean, mop, and put things back together! Grab a bucket and a mop and get swinging. What’s that green stuff? Where did that bone come from? We don''t get paid to ask questions, we get paid to clean!' FROM games WHERE igdb_id = 217139 ON CONFLICT (game_id, language_code) DO NOTHING;
