INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('potionomics', 75994, '2022-10-17', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kdr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1m95.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potionomics', 'Potionomics is a game about the business of brewing and selling magical potions. Sylvia, a penniless young witch, must save her shop from the clutches of a debt collector, but she can’t do it alone. With the help of fellow merchants, fledgling adventurers, and an overbearing owl, Sylvia will master the art of potion brewing and the nuance of salesmanship to rescue her shop. After using magical ingredients to brew up a bevy of potent wares, the budding entrepreneur will wheel and deal to make sales with a colorful cast of fickle customers, all while tackling fierce competition and an ever-changing economy. Along the way she’ll encounter classic RPG creatures and heroes of all sizes. Sprinkle in some magic and players are in for a fantastical adventure unlike any they’ve ever experienced before!' FROM games WHERE igdb_id = 75994 ON CONFLICT (game_id, language_code) DO NOTHING;
