INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pink Takes Shape', 'Pink Takes Shape is a queer metroidvania about exploration and changing shape. Start as a pink blob that can only move and jump. Learn to morph and gain abilities to explore the strange, dark world. Savor the textless environmental storytelling. Decipher what it means to be there, to be you.' FROM games WHERE igdb_id = 325995 ON CONFLICT (game_id, language_code) DO NOTHING;
