INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Directly Drink Milk from Cow', 'The main character comes to work part-time at a ranch and takes care of 16 Holstein cows and their calves. He has to chase the cows with his dog, milk the cows, feed them, and carry the milk in buckets slowly without spilling. You can also take a car to explore and talk to the villagers.' FROM games WHERE igdb_id = 195745 ON CONFLICT (game_id, language_code) DO NOTHING;
