INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Place Like', 'Pour yourself a cup, take your time & enjoy. Choose a cup you''d like to have your coffee in & add in whatever else you like. This is a cozy point & click game, where you can go at your own pace - there is no end goal, make as much coffee as you like! There are also 6 hidden little coffee beans for you to find in the kitchen. Remember, there''s no place like home (whatever home might mean for you).' FROM games WHERE igdb_id = 215430 ON CONFLICT (game_id, language_code) DO NOTHING;
