INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manor of Shadows', 'Manor of Shadows is a top-down 2D RPG/JRPG with puzzle and psychological horror elements. The story follows a girl named Melialor who becomes trapped inside a mysterious mansion and must explore its rooms trying to escape, uncovering evidence of a bigger secret hidden within the house as the investigation progresses.' FROM games WHERE igdb_id = 380678 ON CONFLICT (game_id, language_code) DO NOTHING;
