INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossybara', 'Small-Leaf the Capybara lost the fruit he was going to bring to the hot spring to stack ontop of his head! can you help him scavenge for the lost fruit and save the day? Crossybara: Nonogram Slam! is a new take on the regular Nonogram/Picross puzzle, Instead of solving the puzzle to reveal a picture, you are solving to reveal the level. loads of enjoyable platforming gameplay with a side dish of brain-bamboozling puzzles!' FROM games WHERE igdb_id = 310911 ON CONFLICT (game_id, language_code) DO NOTHING;
