INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroish', 'Play as one of six epic heroes, summon troops, sling spells, and destroy enemy towers to achieve victory in this exciting head-to-head castle defense game. Players can enjoy single-player adventures with three campaigns filled with campy storytelling, sweeping musical scores, and hand-crafted environments. Or they can dive into fast-paced battles with friends and family in competitive 1v1 or 2v2 matches. Players can build custom decks and upgrade cards to create monstrous combinations of troops and spells as they aim to defeat their opponents, destroy the Soul Gem that gives them power, and move to the top of the leaderboards.' FROM games WHERE igdb_id = 207215 ON CONFLICT (game_id, language_code) DO NOTHING;
