INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Lover 2: Forgotten Truth', 'In River City, there is an ordinary milk tea shop, but with one peculiar thing about it - almost every day there is a huge line in front of it. Is it just due to its popularity? Or is someone specifically hiring people to stand in that line? And if the second is true, then what is the reason for this - is someone playing some dirty game against the owner of the tea shop, or is there even greater conspiracy behind all this?' FROM games WHERE igdb_id = 275490 ON CONFLICT (game_id, language_code) DO NOTHING;
