INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Mage - Phantom Twilight', 'Wild Mage - Phantom Twilight is a multiplayer, open-world action RPG made for small team based adventures, featuring airships, floating islands, dungeons, and next-gen combat. Monsters can be dynamically sliced into pieces. Terrain and structures can be altered or destroyed. Abilities and spells can be acquired from monsters and lore books. A game that brings adventure back to the genre.' FROM games WHERE igdb_id = 84001 ON CONFLICT (game_id, language_code) DO NOTHING;
