INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irritating Ship', 'Navigate a winding corridor filled with obstacles in this new precision-movement game for the NES, rotating your ship and accelerating forward in the frictionless environment of space. Three difficulties determine the number of lives gained from each checkpoint, and gravity can be toggled on for additional challenge. A secret ending and hidden mode can be uncovered by the most skilled of players.' FROM games WHERE igdb_id = 256776 ON CONFLICT (game_id, language_code) DO NOTHING;
