INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NinNinDays 2', 'A young man is dazing off while working the night shift at a convenience store, when a girl stops in to ask for a meat bun. The one next to her appears to be her boyfriend, and after doing their shopping, the two of them link arms affectionately and take off. Just when the young man is thinking how nice it would be to have a girlfriend, a pair of girls in ninja cosplay show up.' FROM games WHERE igdb_id = 230799 ON CONFLICT (game_id, language_code) DO NOTHING;
