INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Journey', 'Train Journey is a 16-cartridge PICO-8 game (the maximum size) about a mysterious train to which the player is seemingly bound. Travel between stops, meet unique characters, and learn their stories. Can you free yourself and return home? Or will you ride the train forever...?' FROM games WHERE igdb_id = 382209 ON CONFLICT (game_id, language_code) DO NOTHING;
