INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('little-mouses-encyclopedia-plus-under-leaves', 188099, '2022-01-21', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1e06.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Mouse''s Encyclopedia + Under Leaves', 'Little Mouse''s Encyclopedia is ideal for born explorers. Wandering around the lively boards, you’ll find animals and plants by yourself. Using a magnifying glass, you can reveal cards that contain interesting information and drawings. GORGEOUS ILLUSTRATIONS The graphic style of Little Mouse''s Encyclopedia was inspired by classic fairy tales and... children''s encyclopedias. This enchanting and original style makes the exploration even more enjoyable, and various animations breathe life into the surroundings. While playing, listen to pleasant, relaxing music and the sounds of nature, such as birds chirping or frog toad. EXPLORE THE WORLD With a brave mouse, you’ll explore the area around its burrow, walk through the forest, sneak through the garden and swim in the pond. In each of these places, unique species of animals and plants await you. During your wandering, you’ll come across over 160 unique species, about which you can learn something interesting.' FROM games WHERE igdb_id = 188099 ON CONFLICT (game_id, language_code) DO NOTHING;
