INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherman''s Quest', 'An outgoing, outdoor-loving, yellow rabbit named Sherman must leave his ill, bed-ridden wife, Alice, at home to rescue his grandchildren, Rodder and Mopsy, from the clutches of the self indulgent crow king, Velcrow. Along the way, you''ll even meet up with a few friendly faces, and some challenges to test your consistency.
