INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krispee Street', 'Based on the popular webcomic, this emotional (in a good way!) hidden object game features hundreds of quirky characters and items to seek and find. Jump into the quirky, curious, and feels-like-a-warm-hug world of Krispee, the webcomic. Sure to make you laugh, smile, and maybe even cry — but just a little bit! — Krispee Street is all the feels you never knew you needed.' FROM games WHERE igdb_id = 187786 ON CONFLICT (game_id, language_code) DO NOTHING;
