INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('laser-cannon-3', 207814, '2022-03-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ect.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser Cannon 3', 'A monster shooter wanted! They are clever and tend to hide in deep holes and behind steel gates. Only a smart shooter can get them. Are you the one? Pass all the levels of the physics game online free and prove a sharp shooter. Shoot explosives to hit few targets at once and gain combo. The less shots it takes to pass a level, the more stars you gain. You can replay any physics-based puzzles as much as you want, because full version game is available free online without limitation or registration. Can you collect all achievements in the logic shooting game? Find it out now!' FROM games WHERE igdb_id = 207814 ON CONFLICT (game_id, language_code) DO NOTHING;
