INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mad-burger-3-wild-west', 102040, '2022-02-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ecq.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Burger 3: Wild West', 'Welcome to the Wild West in the third part of the throwing games series. Help the cowboy toss a burger as far as possible and thus impress a beautiful lady watching him from the saloon window. Buy various upgrades to let your hamburger fly farther. Enjoy the classic frontier setting as you play arcade games online for free. With cowboys and bandits, it’s a fun game for boys of any age. Cartoon artwork and family-friendly gameplay makes this launching game an enjoyable pastime. If you enjoy arcade and action games which require no download, our portal has lots of them.' FROM games WHERE igdb_id = 102040 ON CONFLICT (game_id, language_code) DO NOTHING;
