INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sofiya and the Ancient Clan', 'Sofiya and the Ancient Clan is a traditional side-scrolling action platformer presented in vibrant pixel art style with fluid animations. Run, jump and cast spells as you traverse hills and forests, caverns, castle walls, graveyards and more. Use your magic to trigger secret switches, make new platforms appear, incapacitate guards or take down vicious ogres, ghosts and a wide variety of other enemy types. Face off against monstrous bosses at the end of each region you clear, and victory will be rewarded with saucy unlockable images to fill your gallery!' FROM games WHERE igdb_id = 209648 ON CONFLICT (game_id, language_code) DO NOTHING;
