INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fazbear Nights 2: Quaesitor Mortis', 'After a long hiatus, Fazbear Entertainment welcomes you back to a brand new establishment! As Fredbear and Friends went out on indefinite vacation, it is time for new faces to take the stage and bring the joy to unprecedented levels! With outstanding ahead-of-their-time security technologies, you and your children will be safer at Freddy''s than in your own home, so come on in and invite yourself to a delicious pizza, served by yours truly, Freddy Fazbear.' FROM games WHERE igdb_id = 315373 ON CONFLICT (game_id, language_code) DO NOTHING;
