INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cop-car-police-simulator-chase', 187469, '2022-01-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4gpt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1d1v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cop Car Police Simulator Chase', 'Experience the exciting day-to-day life of an US police officer in Police Squad Simulator. Discover a large, lively and freely-accessible US city and ensure the safety in your district. Record traffic accidents, search for stolen vehicles and arrest criminals. Support other police officers at traffic checkpoints, flag down speeders and write them up. Stop and check every citizen or car you want and enforce the law. Pay attention to fugitive suspects and chase them on foot or by car with lights flashing and sirens blaring. Investigate crime scenes, interrogate witnesses and search for evidence. Get behind the wheel of three realistically recreated police vehicles with functional cockpits and use the in-car-computer to identify wanted suspects and stolen vehicles. Start with a typical police sedan and change to an all-terrain SUV and a fast police muscle car while you progress in the game. Use the siren to stop cars or to pave your way through heavy traffic in an emergency. If you crash or damage your car, you will not only have visible crash deformations, the handling of the car will also become more difficult.' FROM games WHERE igdb_id = 187469 ON CONFLICT (game_id, language_code) DO NOTHING;
