INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VoidGate', 'VoidGate is a third-person Diablo style dungeon crawling game. It consists of randomly generated dungeons, lite survival elements, and permanent death. The combat consists of strategic real-time action, using different styles of melee combat, ranged combat, and magic. There is no class system, as it allows absolute freedom of the player to choose their attributes, stats, and skills. However, there are some class archetypes for players who may want to choose a narrower suggested path.' FROM games WHERE igdb_id = 111447 ON CONFLICT (game_id, language_code) DO NOTHING;
