INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merchant Adventurer', 'An economic and political simulation that takes place in the late Medieval and early Renaissance ages. Players represent a family that attempts to gain wealth through business associations and governments throughout Europe. The game features share and bond investment, trading, taxes and tariffs, exploration, combat and mercenaries, diplomacy, charters, and piracy. Hundreds of historic civilizations from all around the world are playable.' FROM games WHERE igdb_id = 299654 ON CONFLICT (game_id, language_code) DO NOTHING;
