INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towards Future', 'Waking up in the darkness, unable to see the sunrise, he remembered the little master carefully carried him home. The base has already fallen into ruin and there are no signs of any living people here. Where did the little master go? Is there any hope left under the doomsday?' FROM games WHERE igdb_id = 320622 ON CONFLICT (game_id, language_code) DO NOTHING;
