INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Photophobia', 'Explore the abandoned city of Kriladam as you hide from the streetlights, as the city''s electrical network itself is bent on killing you. Search the abandoned houses for a way to the network''s mainframe as you slowly uncover the truth of the tragedy that struck the city years ago, with people turning up missing or dead every single day. Solve puzzles caused by the disrepair of the city and dodge the light as you try to destroy the machine. (from Itch.io)' FROM games WHERE igdb_id = 379640 ON CONFLICT (game_id, language_code) DO NOTHING;
