INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyball', 'Cyball CyBall is a futuristic football-themed (US: soccer), NFT-based game where users can collect and form a team of CyBlocs and face off against other teams online, or trade and mentor new CyBlocs within the CyBall''s ecosystem. Initially, the game will launch on BNB Chain with immediate plans to launch on Solana as soon as it is ready to create a multi-chain gaming environment.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 225843 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
