INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gladom: The 2D MOBA in Pixel Art', 'MOBA in 2D Pixel Art fully online PVP oriented. Select your unique hero to fight in teams of 4v4. Gain gold by last hitting stone minions, killing enemy heroes or destroying towers. Use gold to buy items at the shop to increase your power. Competitiveness and game balance are our main goals.' FROM games WHERE igdb_id = 121469 ON CONFLICT (game_id, language_code) DO NOTHING;
