INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stella of the End', 'Stella of the End is a post-apocalyptic kinetic novel made by Romeo Tanaka in collaboration with the visual novel studio Key, which follows transporter Jude Gray, who accepts a request to deliver a gynoid named Filia to the top of a space elevator while avoiding dangers from human bandits and machines who have created a "singularity".' FROM games WHERE igdb_id = 140634 ON CONFLICT (game_id, language_code) DO NOTHING;
