INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-alliance', 197788, '2022-03-14', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scgo1h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Alliance', 'This a strategy game all about enemy troops trying to break through your defences at any cost. Choose a location, plan your strategy and lead your troops to victory. You alone decide how to use budget available to you – to buy new weapons or to improve and strengthen existing ones. A number of weapons systems (infantry, artillery, high-tech weapons, navy) are available to you. Since the enemy attacks with different kinds of units, it is essential to make the right choice and the right placement. However, make sure that you have only limited resources available and that the weapons systems have different characteristics. If the situation gets too tricky, you''ll need air support. But be careful. The enemy has the same options as you! The intelligently designed maps and the wide selection of weapons open up a variety of tactical possibilities and countless hours of entertainment.' FROM games WHERE igdb_id = 197788 ON CONFLICT (game_id, language_code) DO NOTHING;
