INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saiko no Sutoka no Shiki', 'Saiko no Sutoka Halloween Edition is a spin-off of the original game Saiko no Sutoka, in which Saiko is a zombie anime girl who wants to play with her senpai, with the senpai needing to complete her parts and give her food to satisfy her hunger while simultaneously trying to escape.' FROM games WHERE igdb_id = 244705 ON CONFLICT (game_id, language_code) DO NOTHING;
