INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life Eternal', 'A necromancer awakens in a dilapidated tower he once knew as a pristine stronghold for his lord and sorcerer that he was apprenticed under. Somehow, the necromancer slept through it all in a sleep so sound, not even his lord''s death woke him up. But that''s all right; his lord had foreseen this coming and made sure the necromancer had the knowledge and training so he could raise his dead lord all on his own.' FROM games WHERE igdb_id = 225235 ON CONFLICT (game_id, language_code) DO NOTHING;
