INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biohazard Village: Cloud Z Version', 'Resident Evil Village is a first-person survival horror game and the sequel to Resident Evil 7: Biohazard. The game maintains elements from previous Resident Evil games, with players having to scavenge environments for items and manage their resources. However, it adds more action-oriented gameplay, with higher enemy counts and a greater emphasis on combat.' FROM games WHERE igdb_id = 251751 ON CONFLICT (game_id, language_code) DO NOTHING;
