INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traction Control', 'Traction Control is a prototype downhill exploration racer where only some of the laws of physics apply. Pick your vehicle and drift, jump, flip, spin, roll, and boost through a series of time and point-based challenges to get to the top of the leaderboard. The game evokes early kart-racing games and will keep you thinking of the best way to get down the mountain to the finish line!' FROM games WHERE igdb_id = 148236 ON CONFLICT (game_id, language_code) DO NOTHING;
