INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire: The Masquerade - Heartless Symphony', 'Vampire: The Masquerade – Heartless Symphony is an upcoming narrative RPG set in the World of Darkness, developed by Entalto Studios. Expanding on the events of Vampire: The Masquerade – Heartless Lullaby, the game follows multiple characters through a dark urban story shaped by player choices rather than dice rolls. Featuring character customization, skill progression, and branching narratives with multiple endings, the game is expected to offer a 10–15 hour experience with side quests and several playable perspectives. With a hand-drawn art style inspired by Disco Elysium, Heartless Symphony aims to provide an accessible entry point to the World of Darkness for both newcomers and longtime fans.' FROM games WHERE igdb_id = 394759 ON CONFLICT (game_id, language_code) DO NOTHING;
