INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Into the Underdusk', 'A stagnant world slowly sinking into the depths of forgetfulness. You alone must brave this world on a quest to regain your lost locket and regain your memories before it''s too late. Choose your path through an eery pixel art landscape, brave brutal precision-platforming gauntlets, meet strange denizens and grab collectibles to increase your powerset in a bid to regain your very soul.' FROM games WHERE igdb_id = 194894 ON CONFLICT (game_id, language_code) DO NOTHING;
