INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amnea 28: Dve Vechnosti', 'Amnea 28 is a story about a group of young people who go to listen to a course of lectures by a respected professor of psychology. The purpose of the trip is the old hotel "Amnea", which ceased to fulfill its main functions ten years ago, and now serves as a secluded corner for the professor. During the week of studying, each new day the atmosphere is inexorably changing.
