INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z-Warp', 'Z-Warp is an intense vertical shoot''em up presented in retro pixel art style, featuring frenetic arcade-inspired action where blasters, bombs and killer specials are your only allies. Shoot down demonic enemies as they try to overwhelm your ship with bullet hell salvos and turn the tide of battle by charging your killer weapon capable of instantly wiping out anything in a tight radius around your ship! Face massive boss abominations and aim for high scores in Story or Endless modes.' FROM games WHERE igdb_id = 192278 ON CONFLICT (game_id, language_code) DO NOTHING;
