INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plunderer''s Adventures', 'Plunderer''s Adventures is a pixel art tower defense action game where you use your trusty flintlock pistol and every trick up your sleeve to take down your opponents. Blast enemies as they cross the screen towards your crew. Take them down quickly and efficiently, and your crew will support you with extra lives, loot multipliers and more, but fail to protect them from the onslaught, and they''ll be carried off by malicious marauders! By clearing enemy waves, you''ll unlock new stages, skills, crew members, gallery images and more.' FROM games WHERE igdb_id = 192074 ON CONFLICT (game_id, language_code) DO NOTHING;
