INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wildstandz', 357405, '2022-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa7do.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WildStandZ', 'WildStandZ is a multiplayer zombie action shooter for first-person survival with an open world in which you will have to lead a small squad of survivors. Every night can be the last! Every God-forsaken wasteland keeps its secrets! Every choice has unturned consequences! This is a new story, a new destiny, end of which you will shape yourself. Try to survive - hordes of zombies want to taste the flesh and blood - there are plenty of them here, survival is your priority! Use a variety of weapons: knives, grenades, rifles, pistols - the remains of the military base now belong to you. Fight the virus that has struck the planet: study locations (laboratory, bunker, abandoned city), collect items, look for food and ammunition - they will definitely come in handy. Form clans and alliances with other survivors, create bases and shelters - this is the only way to defeat the walking dead. Or be a loner, fight enemies and loot the bases of other players. However, you must remember that there are zombies, zombies and zombies around!' FROM games WHERE igdb_id = 357405 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 357405 AND p.igdb_id = 34 ON CONFLICT DO NOTHING;
