INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ryclaw: Hope', 'Ryclaw: Hope is a short kinetic novel about a young girl named Sakura who has spent most of her life in the hospital. Coming home for the first time in months, Sakura has a dream that she wants to make a reality. You play as her older brother, who has raised Sakura since the passing of their parents. Spend time with your precocious little sister and help her wish come true.' FROM games WHERE igdb_id = 211748 ON CONFLICT (game_id, language_code) DO NOTHING;
